fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left: usize = 0;
    let mut right: usize = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;

        if v[mid] == k {
            return mid;
        } else if v[mid] < k {
            left = mid + 1;
        } else {
            // v[mid] > k
            // since mid could be zero, ensure no underflow on right
            if mid == 0 {
                // mid == 0 and v[mid] > k means k can't be in the array contradicting assumption
                // But since k guaranteed in array, this won't happen; still safeguard
                break;
            }
            right = mid - 1;
        }
    }

    // By problem assumption, k is guaranteed to appear in v,
    // so this point should never be reached.
    // But to satisfy compiler: return left as fallback.
    left
}